{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A massive iron gate, rusted and half-crumbled, stands before a fog-filled city. The glass diver steps forward, diving helmet reflecting broken spires.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a map under a shattered archway.",
      "visual_description": "Mara spreads a large ink-stained map on a stone block, compass in hand, as the glass diver peers over her shoulder. Rubble and faded banners line the street.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A glowing eye flickers inside an oil lamp atop a broken pillar; its flame casts long shadows. The glass diver and Mara pause, listening.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts a narrow alley filled with old royal banners.",
      "visual_description": "The small metal fox scurries through a dim alley, its key-wind tail clicking, passing tattered banners bearing faded crests. It stops to sniff a rusted flagpole.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver peers through a cracked window into a courtyard.",
      "visual_description": "The glass diver presses his helmet against a grimy window, seeing a courtyard with overturned carts and abandoned stalls. His reflection ripples in the cracked glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks the location of a magic door on her map.",
      "visual_description": "Mara kneels by a stone wall, tracing a faint glowing sigil with her ink-stained fingers, adding it to her map. The glass diver watches from behind.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns that the magic door leads to a trap.",
      "visual_description": "Inside a dim chamber, the oracle lamp's flame flutters urgently as it speaks. The glass diver hesitates before the glowing door, hand on its handle.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox discovers a hidden passage beneath a fallen statue.",
      "visual_description": "The tin fox digs at the base of a toppled stone figure, revealing a dark opening. Dust and broken chain links scatter around.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector snores in a collapsed tower room.",
      "visual_description": "In a dusty room with a collapsed ceiling, the tax collector sleeps on a pile of ledgers, stamped papers stuck to his sleeves. A single beam of light illuminates him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Mara leads the glass diver through the hidden passage.",
      "visual_description": "Mara holds a lantern low as she and the glass diver crouch through a narrow stone tunnel, the tin fox ahead, eyes glowing.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "They emerge in a throne room filled with cursed treasures.",
      "visual_description": "A vast hall with a cracked marble throne, piles of gold and jewels glittering under dust motes. Faded royal banners hang from the ceiling.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp reveals the cursed nature of the treasure.",
      "visual_description": "The oracle lamp sits atop a heap of coins, its eye-like flame casting a warning glow. The glass diver and Mara step back from the tempting piles.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols march through the streets above.",
      "visual_description": "Through a grate in the underground passage, the glint of metal boots and the sound of rhythmic footsteps echo. The group freezes in the shadows.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector wakes briefly, then dozes again.",
      "visual_description": "The tax collector stirs, blinks at the group, mutters 'taxes...' and falls back asleep on his ledger pillow. Papers flutter around him.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver swims through a mirror into a locked chamber.",
      "visual_description": "The glass diver presses his helmet against a tall mirror, then steps through as if into water, emerging in a stone room with a single locked chest.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Mara finds the key to the magic door on her map.",
      "visual_description": "Mara traces a hidden line on her map, revealing a key symbol. She holds the map up to the light, nodding to the tin fox.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They escape the city across a crumbling bridge.",
      "visual_description": "A stone bridge spanning a chasm, with missing sections and crumbling railings. The glass diver, Mara, tin fox, and a drowsy tax collector hurry across as the city behind them begins to collapse.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The oracle lamp flickers farewell at the bridge's end.",
      "visual_description": "At the far side of the bridge, the oracle lamp's flame dims and winks out, leaving a single puff of smoke. The group looks back at the ruined city in the distance.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

